package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.sql.Date;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import net.officefloor.hq.app.claim.Late;
import net.officefloor.hq.app.sheet.SheetClock;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/**
 * The settings kept per sheet, by key; a key with no value set takes its default. A setting that carries a figure is
 * {@link #dated}: it keeps a value per from-date, the one in force on a date being that of the latest from-date on or
 * before it; the others keep one value.
 */
@Repository
public class Settings {

    /** The due a clerk may settle at most (two decimals); blank: no limit. */
    public static final String CLERK_LIMIT = "clerk-limit";

    /** The most a person's due-total is (two decimals); blank: no cap. */
    public static final String CAP = "cap";

    /** The due above which a claim needs a proof before it is settled or approved (two decimals); blank: none. */
    public static final String PROOF_THRESHOLD = "proof-threshold";

    /** The least a claim's live due is (two decimals); blank: its default. */
    public static final String FLOOR = "floor";

    /** The days after its date by which a claim is due (a whole number); blank: its default. */
    public static final String TERMS = "terms";

    /** The grades that may have terms of their own, each under the key terms-<grade>. */
    public static final List<String> GRADES = List.of("A", "B", "C");

    /** The key of a grade's own terms (a whole number of days); blank: the sheet's terms. */
    public static String gradeTerms(String grade) {
        return TERMS + "-" + grade;
    }

    /** The percent of an overdue claim's figure charged for every full 30 days it is overdue (two decimals). */
    public static final String LATE_PCT = "late-pct";

    /** The date before which a claim rounds half up, on or after it half to even (yyyy-MM-dd); blank: the sheet's today. */
    public static final String POLICY_DATE = "policy-date";

    /** The date from which (on the sheet's today) a claim opened is numbered within its period (yyyy-MM-dd); blank: off. */
    public static final String PERIOD_NUMBERING_FROM = "period-numbering-from";

    /** The actions whose roles the permission matrix sets, each under the key perm-<action>. */
    public static final List<String> PERMISSIONS = List.of("open", "settle", "void", "reassign", "close", "reopen");

    /** The key of an action's permitted roles (a comma separated list of roles); blank: its standing rule. */
    public static String perm(String action) {
        return "perm-" + action;
    }

    /** The roles that may take the action under the standing rule: reassign and reopen a steward, the rest any. */
    public static String defaultPerm(String action) {
        return "reassign".equals(action) || "reopen".equals(action) ? "steward" : "clerk,steward";
    }

    /** The late percent a sheet starts with. */
    public static final String DEFAULT_LATE_PCT = "0.00";

    /** The terms a sheet starts with. */
    public static final String DEFAULT_TERMS = "14";

    /** The floor a sheet starts with. */
    public static final String DEFAULT_FLOOR = "1.00";

    /** Whether the key is dated: every setting that carries a figure is; the policy and period numbering dates are not. */
    public static boolean dated(String key) {
        return !POLICY_DATE.equals(key) && !PERIOD_NUMBERING_FROM.equals(key) && !key.startsWith("perm-");
    }

    /** The from-date an undated setting's one value is kept under. */
    private static final Date UNDATED = Date.valueOf(LocalDate.of(1, 1, 1));

    private final JdbcTemplate jdbc;

    private final SheetClock clock;

    public Settings(JdbcTemplate jdbc, SheetClock clock) {
        this.jdbc = jdbc;
        this.clock = clock;
    }

    /** The value set for an undated key, or "" when none is. */
    public String get(String sheet, String key) {
        List<String> found = jdbc.queryForList("SELECT setting_value FROM setting WHERE sheet = ? AND setting_key = ?",
                String.class, sheet, key);
        return found.isEmpty() ? "" : found.get(0);
    }

    /** The value of a dated key in force on the date, or "" when none is recorded on or before it. */
    public String on(String sheet, String key, LocalDate date) {
        List<String> found = jdbc.queryForList("SELECT setting_value FROM setting WHERE sheet = ? AND setting_key = ?"
                + " AND from_date <= ? ORDER BY from_date DESC LIMIT 1", String.class, sheet, key, Date.valueOf(date));
        return found.isEmpty() ? "" : found.get(0);
    }

    /** The values recorded for a dated key, by from-date. */
    public List<DatedValue> history(String sheet, String key) {
        return jdbc.query("SELECT from_date, setting_value FROM setting WHERE sheet = ? AND setting_key = ? ORDER BY from_date",
                (rs, i) -> new DatedValue(rs.getDate(1).toLocalDate().toString(), rs.getString(2)), sheet, key);
    }

    /** Sets an undated key's value. */
    public void set(String sheet, String key, String value) {
        set(sheet, key, null, value);
    }

    /** Records the key's value from the from-date (an undated key ignores it), replacing one already recorded from it. */
    public void set(String sheet, String key, LocalDate from, String value) {
        Date date = dated(key) && from != null ? Date.valueOf(from) : UNDATED;
        jdbc.update("MERGE INTO setting (sheet, setting_key, from_date, setting_value) KEY (sheet, setting_key, from_date)"
                + " VALUES (?, ?, ?, ?)", sheet, key, date, value);
    }

    /** The dated key's figure by date, starting (before every from-date, or where a blank is in force) at the start. */
    private Dated figure(String sheet, String key, BigDecimal start) {
        TreeMap<LocalDate, BigDecimal> values = new TreeMap<>();
        for (DatedValue v : history(sheet, key)) {
            values.put(LocalDate.parse(v.from()), v.value().isEmpty() ? start : new BigDecimal(v.value()));
        }
        return new Dated(start, values);
    }

    /** The sheet's clerk limit in force on its today, or null when there is none. */
    public BigDecimal clerkLimit(String sheet) {
        String limit = on(sheet, CLERK_LIMIT, clock.today(sheet));
        return limit.isEmpty() ? null : new BigDecimal(limit);
    }

    /** The sheet's cap in force on its today: the most a person's due-total is, or null when there is none. */
    public BigDecimal cap(String sheet) {
        String cap = on(sheet, CAP, clock.today(sheet));
        return cap.isEmpty() ? null : new BigDecimal(cap);
    }

    /** The due-total capped at the cap (none: as it is); a null (n/a) due-total is not capped. */
    public static BigDecimal capped(BigDecimal dueTotal, BigDecimal cap) {
        return dueTotal == null || cap == null || dueTotal.compareTo(cap) <= 0 ? dueTotal : cap;
    }

    /** The sheet's proof threshold in force on the date, or null when there is none. */
    public BigDecimal proofThreshold(String sheet, LocalDate date) {
        String threshold = on(sheet, PROOF_THRESHOLD, date);
        return threshold.isEmpty() ? null : new BigDecimal(threshold);
    }

    /** The sheet's floor by date: the least a claim's live due is, the one in force on the claim's date. */
    public Dated floor(String sheet) {
        return figure(sheet, FLOOR, new BigDecimal(DEFAULT_FLOOR));
    }

    /** The sheet's terms in force on the date: the days after its date by which a claim is due. */
    public int terms(String sheet, LocalDate date) {
        String terms = on(sheet, TERMS, date);
        return Integer.parseInt(terms.isEmpty() ? DEFAULT_TERMS : terms);
    }

    /**
     * The terms of the grade in force on the date: its own when it has them then, else the sheet's (a null grade takes
     * the sheet's).
     */
    public int terms(String sheet, String grade, LocalDate date) {
        String own = grade == null ? "" : on(sheet, gradeTerms(grade), date);
        return own.isEmpty() ? terms(sheet, date) : Integer.parseInt(own);
    }

    /**
     * The sheet's late percent by date: charged on an overdue claim's figure for every full 30 days it is overdue, the
     * one in force on the claim's date.
     */
    public Dated latePct(String sheet) {
        return figure(sheet, LATE_PCT, new BigDecimal(DEFAULT_LATE_PCT));
    }

    /** What makes the sheet's late charges on its today. */
    public Late late(String sheet, LocalDate today) {
        String policy = get(sheet, POLICY_DATE);
        return new Late(latePct(sheet), today, policy.isEmpty() ? today : LocalDate.parse(policy));
    }

    /** The date from which claims opened are numbered within their period, or null when they are not. */
    public LocalDate periodNumberingFrom(String sheet) {
        String from = get(sheet, PERIOD_NUMBERING_FROM);
        return from.isEmpty() ? null : LocalDate.parse(from);
    }

    /** Whether the permission matrix lets the role take the action (a blank entry: the standing rule). */
    public boolean permits(String sheet, String action, String role) {
        String roles = get(sheet, perm(action));
        return List.of((roles.isEmpty() ? defaultPerm(action) : roles).split(",")).contains(role);
    }

    /** The settings in force on the sheet's today, with every dated key's recorded values. */
    public SettingsResponse all(String sheet) {
        LocalDate today = clock.today(sheet);
        Map<String, List<DatedValue>> dated = new LinkedHashMap<>();
        for (String key : List.of(CLERK_LIMIT, CAP, FLOOR, TERMS, gradeTerms("A"), gradeTerms("B"), gradeTerms("C"), LATE_PCT, PROOF_THRESHOLD)) {
            dated.put(key, history(sheet, key));
        }
        Map<String, String> perms = new LinkedHashMap<>();
        for (String action : PERMISSIONS) {
            perms.put(action, get(sheet, perm(action)));
        }
        return new SettingsResponse(on(sheet, CLERK_LIMIT, today), floor(sheet).on(today).toPlainString(),
                Integer.toString(terms(sheet, today)), latePct(sheet).on(today).toPlainString(), get(sheet, POLICY_DATE),
                get(sheet, PERIOD_NUMBERING_FROM), on(sheet, gradeTerms("A"), today), on(sheet, gradeTerms("B"), today),
                on(sheet, gradeTerms("C"), today), on(sheet, CAP, today), on(sheet, PROOF_THRESHOLD, today), perms, dated);
    }
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;
import net.officefloor.hq.app.role.Role;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateSetting {
    private static final Pattern LIMIT = Pattern.compile("\\d{1,7}(\\.\\d{1,2})?");
    private static final Pattern DAYS = Pattern.compile("\\d{1,4}");

    public void validate(@RequestBody SettingRequest request, Out<SettingInput> body) throws InvalidSettingException {
        SettingInput input = input(request);
        // A dated key may be given the date it is in force from; blank: the sheet's today.
        String from = request == null || request.from() == null ? "" : request.from().trim();
        if (Settings.dated(input.key()) && !from.isEmpty()) {
            try {
                input = input.withFrom(LocalDate.parse(from));
            } catch (DateTimeParseException e) {
                throw new InvalidSettingException("The from-date must be a date (yyyy-mm-dd), or blank");
            }
        }
        body.set(input);
    }

    private SettingInput input(SettingRequest request) throws InvalidSettingException {
        String key = request == null || request.key() == null ? "" : request.key().trim();
        String value = request == null || request.value() == null ? "" : request.value().trim();
        if (!Settings.CLERK_LIMIT.equals(key) && !Settings.CAP.equals(key) && !Settings.PROOF_THRESHOLD.equals(key) && !Settings.FLOOR.equals(key) && !Settings.TERMS.equals(key)
                && !Settings.LATE_PCT.equals(key) && !Settings.POLICY_DATE.equals(key)
                && !Settings.PERIOD_NUMBERING_FROM.equals(key)
                && Settings.GRADES.stream().noneMatch((g) -> Settings.gradeTerms(g).equals(key))
                && Settings.PERMISSIONS.stream().noneMatch((a) -> Settings.perm(a).equals(key))) {
            throw new InvalidSettingException("No such setting: " + key);
        }
        // An action's permitted roles are a comma separated list of clerk and steward; blank keeps its standing rule.
        if (key.startsWith("perm-")) {
            List<String> roles = new ArrayList<>();
            for (String role : value.isEmpty() ? new String[0] : value.split(",")) {
                role = role.trim();
                if (!Role.CLERK.equals(role) && !Role.STEWARD.equals(role)) {
                    throw new InvalidSettingException("The roles allowed an action must be clerk or steward, comma separated, or blank");
                }
                if (!roles.contains(role)) {
                    roles.add(role);
                }
            }
            return new SettingInput(key, String.join(",", roles));
        }
        // The policy date is a date; blank follows the sheet's today.
        if (Settings.POLICY_DATE.equals(key)) {
            if (!value.isEmpty()) {
                try {
                    value = LocalDate.parse(value).toString();
                } catch (DateTimeParseException e) {
                    throw new InvalidSettingException("The policy date must be a date (yyyy-mm-dd), or blank");
                }
            }
            return new SettingInput(key, value);
        }
        // The period numbering from-date is a date; blank turns it off.
        if (Settings.PERIOD_NUMBERING_FROM.equals(key)) {
            if (!value.isEmpty()) {
                try {
                    value = LocalDate.parse(value).toString();
                } catch (DateTimeParseException e) {
                    throw new InvalidSettingException("The period numbering from-date must be a date (yyyy-mm-dd), or blank");
                }
            }
            return new SettingInput(key, value);
        }
        // The terms are a whole number of days; blank takes the default.
        if (Settings.TERMS.equals(key)) {
            if (!value.isEmpty() && !DAYS.matcher(value).matches()) {
                throw new InvalidSettingException("The terms must be a whole number of days, 0 or more, or blank");
            }
            return new SettingInput(key, Integer.toString(Integer.parseInt(value.isEmpty() ? Settings.DEFAULT_TERMS : value)));
        }
        // A grade's own terms are a whole number of days; blank clears them, so the grade takes the sheet's terms.
        if (key.startsWith(Settings.TERMS + "-")) {
            if (!value.isEmpty() && !DAYS.matcher(value).matches()) {
                throw new InvalidSettingException("The terms of a grade must be a whole number of days, 0 or more, or blank");
            }
            return new SettingInput(key, value.isEmpty() ? "" : Integer.toString(Integer.parseInt(value)));
        }
        if (!value.isEmpty() && !LIMIT.matcher(value).matches()) {
            throw new InvalidSettingException("The " + key + " must be 0.00 or more with up to two decimals, or blank");
        }
        // A blank floor or late percent takes its default: they always have a value.
        if (Settings.FLOOR.equals(key) && value.isEmpty()) {
            value = Settings.DEFAULT_FLOOR;
        }
        if (Settings.LATE_PCT.equals(key) && value.isEmpty()) {
            value = Settings.DEFAULT_LATE_PCT;
        }
        return new SettingInput(key,
                value.isEmpty() ? "" : new BigDecimal(value).setScale(2, RoundingMode.UNNECESSARY).toPlainString());
    }
}
package net.officefloor.hq.app.setting;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetClock;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * Saves the setting, a dated one from its from-date (none given: the sheet's today); a floor moves the live dues, so
 * the figures it moved are audited after it.
 */
public class SaveSetting {
    public void save(@PathVariable("sheet") String sheet, @RequestParam("user") String user, @Val SettingInput input,
            Settings settings, SheetClock clock, Audit audit, Rollup rollup) {
        Rollup.Snapshot before = rollup.take(sheet);
        settings.set(sheet, input.key(), input.from() == null ? clock.today(sheet) : input.from(), input.value());
        audit.record("SETTING_CHANGED sheet=" + sheet + " by=" + user + " key=" + input.key() + " value="
                + input.value() + (input.from() == null ? "" : " from=" + input.from()));
        rollup.record(sheet, user, before);
    }
}
package net.officefloor.hq.app.setting;

import java.util.List;
import java.util.Map;

/**
 * The sheet's settings as the screen shows them: the clerk limit with two decimals, or "" for no limit; and the floor
 * with two decimals; and the terms, a whole number of days; and the late percent with two decimals; and the policy date
 * (yyyy-MM-dd), or "" for the sheet's today; and the period numbering from-date (yyyy-MM-dd), or "" for off; and each grade's own terms (a whole number of days), or "" when it takes the sheet's; and the cap with two decimals, or "" for no cap; and the proof threshold with two decimals, or "" for none; and each action's permitted roles (comma separated), or "" for its standing rule. Each
 * is the value in force on the sheet's today. And, for each dated key, its values as recorded, by from-date.
 */
public record SettingsResponse(String clerkLimit, String floor, String terms, String latePct, String policyDate,
        String periodNumberingFrom, String termsA, String termsB, String termsC, String cap,
        String proofThreshold, Map<String, String> perms, Map<String, List<DatedValue>> dated) {
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.claim.Late;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.role.Roles;
import net.officefloor.hq.app.setting.Dated;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.SheetClock;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * Closes the period, fixing its due-total now, and each person's on the sheet (the part of it from their claims): the due now of the claims dated in it
 * that counted at the end of its last day (OPEN, PENDING and SETTLED then by their status log, but not a deferred one, nor an unbound open one dated
 * within its person's hold) (a
 * claim with no rate adds nothing). Refuses a role the permission matrix does not let close, a period not on the sheet or one already closed.
 */
public class ClosePeriod {
    public void close(@PathVariable("sheet") String sheet, @PathVariable("period") String period,
            @RequestParam("user") String user, Periods periods, Claims claims, People people, Rates rates, Settings settings,
            SheetClock clock, Roles roles, Audit audit)
            throws InvalidPeriodException {
        if (!settings.permits(sheet, "close", roles.of(sheet, user))) {
            throw new InvalidPeriodException("Your role may not close a period");
        }
        Period found = periods.find(sheet, period);
        if (found == null) {
            throw new InvalidPeriodException("There is no period named " + period);
        }
        if (found.closed()) {
            throw new InvalidPeriodException("The period " + period + " is already closed");
        }
        LocalDate from = LocalDate.parse(found.from());
        LocalDate to = LocalDate.parse(found.to());
        Map<Long, Person> byId = people.list(sheet).stream().collect(Collectors.toMap(Person::id, (p) -> p));
        List<Rate> sheetRates = rates.list(sheet);
        Dated floor = settings.floor(sheet);
        Late late = settings.late(sheet, clock.today(sheet));
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        Map<Long, BigDecimal> perPerson = new LinkedHashMap<>();
        byId.keySet().forEach((id) -> perPerson.put(id, BigDecimal.ZERO.setScale(2)));
        for (Claim claim : claims.list(sheet)) {
            LocalDate date = LocalDate.parse(claim.date());
            Person person = byId.get(claim.person());
            if (person == null || !person.countsOn(claim, to) || date.isBefore(from) || date.isAfter(to)) {
                continue;
            }
            BigDecimal due = claim.due(sheetRates, person.gradeOn(claim.date()), floor, late);
            if (due != null) {
                total = total.add(due);
                perPerson.merge(person.id(), due, BigDecimal::add);
            }
        }
        if (!periods.close(sheet, period, total, perPerson)) {
            throw new InvalidPeriodException("The period " + period + " is already closed");
        }
        audit.record("PERIOD_CLOSED sheet=" + sheet + " by=" + user + " period=" + period + " total="
                + total.toPlainString());
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.sql.Date;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/** The periods kept per sheet. */
@Repository
public class Periods {

    private static final RowMapper<Period> ROW = (rs, i) -> new Period(rs.getString("name"),
            rs.getDate("from_date").toLocalDate().toString(), rs.getDate("to_date").toLocalDate().toString(),
            rs.getBoolean("closed"),
            rs.getBigDecimal("closed_total") == null ? null : rs.getBigDecimal("closed_total").toPlainString(),
            Map.of());

    private static final String COLUMNS = "SELECT name, from_date, to_date, closed, closed_total FROM period";

    private final JdbcTemplate jdbc;

    public Periods(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Every period on the sheet, by from-date. */
    public List<Period> list(String sheet) {
        return jdbc.query(COLUMNS + " WHERE sheet = ? ORDER BY from_date", ROW, sheet).stream()
                .map((p) -> withPeople(sheet, p)).toList();
    }

    /** The period with its people's due-totals fixed when it was closed. */
    private Period withPeople(String sheet, Period period) {
        if (!period.closed()) {
            return period;
        }
        Map<Long, String> people = new LinkedHashMap<>();
        jdbc.query("SELECT person, total FROM period_person_total WHERE sheet = ? AND period = ? ORDER BY person",
                (rs) -> {
                    people.put(rs.getLong("person"), rs.getBigDecimal("total").toPlainString());
                }, sheet, period.name());
        return new Period(period.name(), period.from(), period.to(), period.closed(), period.closedTotal(), people);
    }

    /** The sheet's period of the name, or null when there is none. */
    public Period find(String sheet, String name) {
        List<Period> found = jdbc.query(COLUMNS + " WHERE sheet = ? AND name = ?", ROW, sheet, name);
        return found.isEmpty() ? null : found.get(0);
    }

    /** Whether the date falls inside a closed period of the sheet. */
    public boolean closedOn(String sheet, LocalDate date) {
        Integer n = jdbc.queryForObject(
                "SELECT COUNT(*) FROM period WHERE sheet = ? AND closed AND from_date <= ? AND to_date >= ?",
                Integer.class, sheet, Date.valueOf(date), Date.valueOf(date));
        return n != null && n > 0;
    }

    /** The name of the sheet's period the date falls inside, or null when it is in none. */
    public String nameOn(String sheet, LocalDate date) {
        List<String> found = jdbc.queryForList("SELECT name FROM period WHERE sheet = ? AND from_date <= ? AND to_date >= ?",
                String.class, sheet, Date.valueOf(date), Date.valueOf(date));
        return found.isEmpty() ? null : found.get(0);
    }

    /** Whether the sheet has a period of the name. */
    public boolean named(String sheet, String name) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM period WHERE sheet = ? AND name = ?", Integer.class,
                sheet, name);
